    entidades: [],
    aeo: [{"pergunta":"O que aconteceu?","resposta":"O dólar fechou a quarta-feira com uma variação pequena ante o real, com investidores no Brasil à espera da divulgação de nova pesquisa eleitoral, enquanto no exterior a moeda norte-americana subiu ante boa parte das demais divisas."},{"pergunta":"Qual é o ponto principal?","resposta":"Dólar: Confira a cotação e fechamento diário do dólar comercial"},{"pergunta":"Quais são os dados mais importantes?","resposta":"O dólar à vista encerrou a sessão com variação positiva de 0,14%, a R$5,0298. No ano, a divisa passou a acumular baixa de 8,37%."},{"pergunta":"Qual é o contexto?","resposta":"Às 17h11, o dólar futuro para novembro — o mais negociado no Brasil — subia 0,08% na B3, aos R$5,0485."},{"pergunta":"Quais são os próximos desdobramentos?","resposta":"Na terça, a moeda encerrou a sessão com alta de 0,74%, aos R$5,0227."}],
